SELECT count(*) FROM public.title title WHERE EXISTS (SELECT 1 FROM public.complete_cast cc, public.comp_cast_type cct1, public.comp_cast_type cct2, public.cast_info ci, public.info_type it1, public.info_type it2, public.keyword k, public.movie_info mi, public.movie_info_idx mi_idx, public.movie_keyword mk, public.name n WHERE title.id = mi.movie_id AND title.id = mi_idx.movie_id AND title.id = ci.movie_id AND title.id = mk.movie_id AND title.id = cc.movie_id AND n.id = ci.person_id AND it1.id = mi.info_type_id AND it2.id = mi_idx.info_type_id AND k.id = mk.keyword_id AND cct1.id = cc.subject_id AND cct2.id = cc.status_id AND cct1.kind = 'cast' AND cct2.kind = 'complete+verified' AND it1.info = 'genres' AND it2.info = 'votes' AND (k.keyword = 'murder' OR k.keyword = 'violence' OR k.keyword = 'blood' OR k.keyword = 'gore' OR k.keyword = 'death' OR k.keyword = 'female-nudity' OR k.keyword = 'hospital') AND (mi.info = 'Horror' OR mi.info = 'Action' OR mi.info = 'Sci-Fi' OR mi.info = 'Thriller' OR mi.info = 'Crime' OR mi.info = 'War') AND n.gender = 'm');
